from google.cloud import documentai

def extract_receipt_fields(payload, config=None):
    config = config or {}
    client = documentai.DocumentProcessorServiceClient(
        client_options={"api_endpoint": f"{config['location']}-documentai.googleapis.com"})
    name = client.processor_path(config["project_id"], config["location"], config["processor_id"])
    response = client.process_document(request={"name": name, "raw_document": documentai.RawDocument(
        content=payload["document_bytes"], mime_type=payload["mime_type"])})
    fields, items = {}, []
    for entity in response.document.entities:
        if entity.type_ == "item":
            values = {p.type_.split("/")[-1]: p.mention_text for p in entity.properties}
            items.append({"description": values.get("description"), "quantity": values.get("quantity"), "price": values.get("price")})
        else:
            fields[entity.type_] = entity.mention_text
    return {"receipts": [{"merchant": fields.get("merchant_name"), "tax": fields.get("tax_amount"), "total": fields.get("total_amount"), "items": items}]}

def normalize_expense(expense):
    normalized_expense = {
        "vendor": expense.get('vendor', ''),
        "date": expense.get('date', ''),
        "total": expense.get('total', 0.0),
        "line_items": expense.get('line_items', [])
    }
    return normalized_expense

def validate_document_fields(document):
    required_fields = ['vendor', 'date', 'total']
    for field in required_fields:
        if field not in document or not document[field]:
            return False
    if 'line_items' not in document or not document['line_items']:
        return False
    for item in document['line_items']:
        if 'description' not in item or 'quantity' not in item or 'amount' not in item:
            return False
    return True

from google.cloud import documentai

def get_document_client(config):
    return documentai.DocumentProcessorServiceClient(
        client_options={"api_endpoint": f"{config['location']}-documentai.googleapis.com"})

def normalize_document_response(response):
    fields, items = {}, []
    for entity in response.document.entities:
        if entity.type_ == "line_item":
            values = {p.type_.split("/")[-1]: p.mention_text for p in entity.properties}
            items.append({"description": values.get("description"), "quantity": values.get("quantity"), "amount": values.get("amount")})
        else:
            fields[entity.type_] = entity.mention_text
    return fields, items

def summarize_invoice(invoice):
    summary = {
        "vendor": invoice.get('vendor', ''),
        "date": invoice.get('date', ''),
        "total": invoice.get('total', 0.0),
        "line_items_count": len(invoice.get('line_items', []))
    }
    return summary
